type Result<T> = { kind: "ok"; value: T } | { kind: "error"; message: string };
type Command = { type: "enroll"; course: string } | { type: "progress"; completed: number };
function isCommand(value: unknown): value is Command {
  if (typeof value !== "object" || value === null || !("type" in value)) return false;
  if (value.type === "enroll") return "course" in value && typeof value.course === "string";
  if (value.type === "progress") return "completed" in value && typeof value.completed === "number";
  return false;
}
function parseCommand(text: string): Result<Command> {
  try {
    const value: unknown = JSON.parse(text);
    return isCommand(value) ? { kind: "ok", value } : { kind: "error", message: "invalid command" };
  } catch { return { kind: "error", message: "invalid JSON" }; }
}
function assertNever(value: never): never { throw new Error(`Unhandled: ${String(value)}`); }
function run(command: Command): string {
  switch (command.type) {
    case "enroll": return `Enrolled: ${command.course}`;
    case "progress": return `Completed: ${command.completed}`;
    default: return assertNever(command);
  }
}
const result = parseCommand("{\"type\":\"progress\",\"completed\":12}");
console.log(result.kind === "ok" ? run(result.value) : `Error: ${result.message}`);

